      {
        "type": "join multi",
        "field name": "Variant ID",
        "fields to join": [
          "chromosome",
          "position",
          "reference",
          "alt"
        ],
        "join by": [
          ":",
          "_",
          "/"
        ]
      },
      {
        "type": "raw",
        "field name": "posteriorProbability",
