      },
      {
        "type": "raw",
        "field name": "credibleSetId",
        "raw field": "credibleSetId"
      },
      {
        "type": "raw",
        "field name": "reference",
        "raw field": "reference"
      },
      {
        "type": "raw",
        "field name": "alt",
        "raw field": "alt"
      },
      {
        "type": "raw",
        "field name": "beta",
        "raw field": "beta"
      },
      {
        "type": "raw",
        "field name": "pValue",
        "raw field": "pValue"
      },
      {
        "type": "raw",
        "field name": "position",
        "raw field": "position"
      },
      {
        "type": "raw",
        "field name": "phenotype",
        "raw field": "phenotype"
      }
    ],
    "star key": "Variant ID"
